"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[9497],{555:(e,t,n)=>{n.d(t,{A:()=>o});const o=n.p+"assets/images/tarot_card_roadmap-0cac50cc9d28b00e0b8ec21c6ca85bd6.svg"},2068:e=>{e.exports=JSON.parse('{"permalink":"/blog/ai-broke-product-planning","source":"@site/blog/2026/ai-broke-planning.md","title":"AI Broke Product Planning and There Is No Obvious Way to Fix That","description":"AI-assisted development has made effort estimation wildly unpredictable. Story points are losing their last foothold, roadmaps feel like tarot cards, and the industry has no consensus on what comes next.","date":"2026-04-05T00:00:00.000Z","tags":[{"inline":true,"label":"Product Management","permalink":"/blog/tags/product-management"},{"inline":true,"label":"AI","permalink":"/blog/tags/ai"},{"inline":true,"label":"Agile","permalink":"/blog/tags/agile"},{"inline":true,"label":"Planning","permalink":"/blog/tags/planning"},{"inline":true,"label":"Estimation","permalink":"/blog/tags/estimation"}],"readingTime":6.52,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"AI Broke Product Planning and There Is No Obvious Way to Fix That","description":"AI-assisted development has made effort estimation wildly unpredictable. Story points are losing their last foothold, roadmaps feel like tarot cards, and the industry has no consensus on what comes next.","slug":"ai-broke-product-planning","date":"2026-04-05T00:00:00.000Z","tags":["Product Management","AI","Agile","Planning","Estimation"],"keywords":["story points","AI estimation","vibe coding","agile planning","product roadmap","sprint planning","velocity","software development AI"],"image":"/img/2026/tarot_card_roadmap.svg"},"unlisted":false,"nextItem":{"title":"Can I Get a Senior Management Job by 40? Unlikely, but Let\'s Speculate","permalink":"/blog/senior-pm-career-outlook"}}')},8453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var o=n(6540);const a={},i=o.createContext(a);function s(e){const t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:t},e.children)}},8873:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>o,toc:()=>d});var o=n(2068),a=n(4848),i=n(8453);const s={title:"AI Broke Product Planning and There Is No Obvious Way to Fix That",description:"AI-assisted development has made effort estimation wildly unpredictable. Story points are losing their last foothold, roadmaps feel like tarot cards, and the industry has no consensus on what comes next.",slug:"ai-broke-product-planning",date:new Date("2026-04-05T00:00:00.000Z"),tags:["Product Management","AI","Agile","Planning","Estimation"],keywords:["story points","AI estimation","vibe coding","agile planning","product roadmap","sprint planning","velocity","software development AI"],image:"/img/2026/tarot_card_roadmap.svg"},r=void 0,l={authorsImageUrls:[]},d=[{value:"The two ways story points were never quite right",id:"the-two-ways-story-points-were-never-quite-right",level:2},{value:"The human-made estimation framework no longer works",id:"the-human-made-estimation-framework-no-longer-works",level:2},{value:"Complexity estimation needs a new frame, too",id:"complexity-estimation-needs-a-new-frame-too",level:2},{value:"What this means for roadmaps",id:"what-this-means-for-roadmaps",level:2}];function h(e){const t={em:"em",h2:"h2",hr:"hr",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"cover",src:n(555).A+"",width:"680",height:"820"})}),"\n",(0,a.jsx)(t.p,{children:"As a major PM responsibility, roadmap planning has become controversial over the years. As much as I enjoy short-sight planning for the next quarter, I hate yearly roadmap planning."}),"\n",(0,a.jsx)(t.p,{children:"The latter became a cargo-cult ritual that starts with whispering in October and, as a giant wave, hits everyone in a product organization, continuing in November until final approval in December each year. It sounds straightforward: prioritize a list of initiatives and put them on a timeline. The trick is to make it not look like a commitment."}),"\n",(0,a.jsx)(t.p,{children:"There are probably hundreds of books dedicated to that topic. The only thing I've learned over half a decade: despite the effort you put into planning, it will end up in the trash before Q1 ends."}),"\n",(0,a.jsx)(t.p,{children:"With all the unknowns driving a roadmap to a nonsensical outcome and keeping higher management under the illusion of control, we now have AI in the equation. It accelerates development output, pushing the bottleneck further down the line. With that change, estimating the whole thing becomes even more problematic."}),"\n",(0,a.jsx)(t.p,{children:"Some voices on LinkedIn have declared that AI has killed Agile, even though it had been declared dead more than a decade ago, and renegade voices claim it was never alive. I will skip that broader discussion and focus on planning."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-two-ways-story-points-were-never-quite-right",children:"The two ways story points were never quite right"}),"\n",(0,a.jsx)(t.p,{children:'For the last 15 years, the industry has adopted story points as an abstract concept, loosely replacing the more traditional method of human-hours. I use "loosely" here intentionally because we never reached a global consensus on how to treat story points. And that is OK: the nature of a story point is to be an abstraction, adapted to someone\'s needs.'}),"\n",(0,a.jsx)(t.p,{children:"However, as humanity tends to do, we took a good-on-paper concept and drove it to absurdity."}),"\n",(0,a.jsx)(t.p,{children:"I've encountered two main approaches:"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:'1. Re-labeling human-hours as story points (the "ideal dev day" school)'})}),"\n",(0,a.jsx)(t.p,{children:"Agile preachers in enterprise took a well-known method and repackaged it to sell their methodologies. I'm not blaming them: enterprise leaders needed something they could understand, standardize, quickly adopt, scale, and use to claim victory in becoming an Agile organization. All of which resulted in significant consequences for how the industry operates today. There is plenty of good writing criticizing enterprise Agile frameworks, but I'll leave that for your own consideration."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"2. Measuring complexity with story points"})}),"\n",(0,a.jsx)(t.p,{children:"At the dawn of my career, it took me some time to grasp how this could work. At the team level, it requires both skill and effort to develop a sound estimation process. The main issue is that complexity varies by team and does not always translate across a broader organization, which is precisely why re-labeling human-hours sells so well."}),"\n",(0,a.jsx)(t.p,{children:"An AI agent in software development has totally undermined the first approach and, for the latter, has made measuring complexity even more complex. The new variables added to any complexity assessment (which LLM you're using, how solid your prompts are, who's reviewing the output, whether a security review is required) sit on top of all the traditional ones and interact with them in ways that are hard to predict upfront."}),"\n",(0,a.jsx)(t.p,{children:"I don't have a recipe for fixing that. Instead, let's define the issues and their consequences. Then I'll continue looking for answers and keep you posted."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-human-made-estimation-framework-no-longer-works",children:"The human-made estimation framework no longer works"}),"\n",(0,a.jsx)(t.p,{children:"That is almost an obvious statement at this point. We used to plan capacity based on projected human-hours for a time period (a 2-week sprint, say), estimate tasks in hours or days, and fit those numbers into available capacity. The number of completed points becomes velocity, lower or higher than capacity, but not wildly far from it."}),"\n",(0,a.jsxs)(t.p,{children:["Now, a team with 30 SP capacity in a sprint can close 150 SP. But that number of completed story points doesn't indicate ",(0,a.jsx)(t.em,{children:"what types of tasks"})," were completed. Nor is it a linear regression: completing 150 SP when your capacity is 30 doesn't mean you'll complete 600 SP next sprint."]}),"\n",(0,a.jsx)(t.p,{children:"That number sounds like a profound achievement, and in the same way it signals that the estimation framework needs to be completely reframed."}),"\n",(0,a.jsx)(t.p,{children:'As developers delegate parts of their work to AI agents, they become less certain about when the outcome will arrive. When hundreds of lines of code can be generated in a moment, the conversation shifts from "when is the code written?" to "when will it be stabilized and production-ready?" A developer is still responsible for delivering a working improvement, just with less direct control over how it\'s done.'}),"\n",(0,a.jsx)(t.p,{children:"So asking for an estimate in human-hours no longer makes sense when the human is not entirely the one in charge. Asking AI to provide the estimate instead? Please let me know if that works for you."}),"\n",(0,a.jsx)(t.p,{children:"I don't have solid numbers, and I am very suspicious of anyone who claims they do. Based on my observations, AI agents perform predictably well on relatively simple, monotonous, time-consuming tasks (updating documentation annotations, for example)."}),"\n",(0,a.jsx)(t.p,{children:"But even simple tasks at scale become problematic. If you're updating documentation annotations across 100 repositories, you will inevitably spend time fixing hallucinations. How long does that take? Until it's done."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"complexity-estimation-needs-a-new-frame-too",children:"Complexity estimation needs a new frame, too"}),"\n",(0,a.jsx)(t.p,{children:"So, estimates in hours or story points aren't reliable. But it's not straightforward to measure complexity either."}),"\n",(0,a.jsx)(t.p,{children:"Our perspective on complexity itself needs to change. Previously, we looked at tech stack, library and codebase familiarity, developer experience, the team's prior work on similar tasks, and other team-specific factors."}),"\n",(0,a.jsx)(t.p,{children:"Now, we also need to account for: which LLM we're using (Opus or Qwen), the quality and completeness of the prompt and context, who will review the code and how, what the testing strategy looks like, and what happens if we need to throw away the AI output and write from scratch. Plus: does this require a security review?"}),"\n",(0,a.jsx)(t.p,{children:"No one has all the answers, and anyone claiming otherwise is selling something. Getting this right will require meticulous, team-by-team work. But I firmly believe we need to be estimating complexity, not hours."}),"\n",(0,a.jsx)(t.p,{children:"We just need some time to figure out how."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"what-this-means-for-roadmaps",children:"What this means for roadmaps"}),"\n",(0,a.jsx)(t.p,{children:"All of that productivity shift affects how I, as a PM, construct product roadmaps from quarter to year."}),"\n",(0,a.jsx)(t.p,{children:"From a planning perspective, I've used two approaches:"}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsx)(t.li,{children:"Decompose a big topic into smaller items, estimate them, sum it up, and apply a risk multiplier (30% is my standard)."}),"\n",(0,a.jsx)(t.li,{children:"Assign a bulk of capacity and hope it's enough to cover a capability or initiative."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Over the last five years, both have worked reasonably well. I'd break down whatever was decomposable and provide a guesstimate when requirements were too unclear for a thorough estimate. Neither approach holds up today."}),"\n",(0,a.jsx)(t.p,{children:"AI has given PMs the power to build prototypes and proofs of concept quickly. But it's also made building roadmaps feel like reading tarot cards. I can build almost anything very fast, but how long will it take to ship AI-generated code to a B2B enterprise customer at the expected quality and compliance level? It depends."}),"\n",(0,a.jsx)(t.p,{children:"And that's before mentioning the elephant in the room: the profound uncertainty about how AI is reshaping entire industries, on top of everything else happening in the world."}),"\n",(0,a.jsx)(t.p,{children:"The bottleneck has moved. Before, the question was when the code would be written. Now, the real constraint is stabilization: review, testing, integration, and making something production-ready. That's where time actually goes, and it's where planning needs to focus."}),"\n",(0,a.jsx)(t.p,{children:"The only practical advice I have right now is to stay as flexible as possible."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"This is the beginning of a longer inquiry. I'll keep exploring what estimation might look like in AI-assisted teams and report back."})})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}}}]);